query EntityBacklinksPage($id: UUID!, $spaceId: UUID) {
  entity(id: $id) {
    backlinksList(filter: { spaceId: { is: $spaceId } }) {
      spaceId
      fromEntity {
        id
        name
        spaceIds
        types {
          id
          name
          spaceIds
        }
      }
    }
  }
}
